sys_script.script:
// ============================================================
// BR — TRADE OCR RATIO CALCULATION
// Table: x_birl3_clm_trade_ocr  (adjust to your actual table name)
// When: after insert/update
// ============================================================
(function executeRule(current, previous) {

    gs.info('TradeOCR-BR: Starting ratio calculation for ' + current.getDisplayValue());

    function num(fieldName) {
        var val = current.getValue(fieldName);
        if (val === null || val === '' || val === undefined) return null;
        var parsed = parseFloat(val.toString().replace(/,/g, ''));
        return isNaN(parsed) ? null : parsed;
    }

    function setIfValid(field, value) {
        if (value !== null && value !== undefined && isFinite(value)) {
            current.setValue(field, Math.round(value * 100) / 100);
        }
    }

    try {
        var sales      = num('u_revenue');
        var grossProfit= num('u_gross_profit');
        var netProfit  = num('u_net_profit');
        var interest   = num('u_interest_expense');
        var depreciation = num('u_depreciation');
        var purchases  = num('u_purchases');
        var directExp  = num('u_direct_expenses') || 0;
        var openStock  = num('u_opening_stock');
        var closeStock = num('u_inventory');
        var cogsExtracted = num('u_cogs');
        var ar         = num('u_accounts_receivable');
        var ap         = num('u_accounts_payable');

        // ── COGS: prefer calculated (Opening + Purchases + Direct Exp - Closing), fallback to extracted ──
        var cogs = null;
        if (openStock !== null && purchases !== null && closeStock !== null) {
            cogs = openStock + purchases + directExp - closeStock;
            gs.info('TradeOCR-BR: COGS calculated = ' + cogs);
        } else if (cogsExtracted !== null && cogsExtracted > 0) {
            cogs = cogsExtracted;
            gs.info('TradeOCR-BR: COGS from OCR extraction');
        }

        // ── EBITDA via addback (no tax field on Trade — proprietorships mostly) ──
        var ebitda = null;
        if (netProfit !== null && interest !== null && depreciation !== null) {
            ebitda = netProfit + (interest || 0) + (depreciation || 0);
            gs.info('TradeOCR-BR: EBITDA via addback = ' + ebitda);
        } else {
            gs.warn('TradeOCR-BR: EBITDA could not be calculated — missing net profit/interest/depreciation');
        }

        // ── Percentages ──
        var gpPct     = (sales && sales > 0 && grossProfit !== null) ? (grossProfit / sales) * 100 : null;
        var ebitdaPct = (sales && sales > 0 && ebitda !== null)      ? (ebitda / sales) * 100      : null;

        // ── Day-based ratios ──
        var arDays  = (sales && sales > 0 && ar !== null) ? (ar / sales) * 365 : null;
        var apDays  = (cogs  && cogs  > 0 && ap !== null) ? (ap / cogs) * 365  : null;
        var invDays = (cogs  && cogs  > 0 && closeStock !== null) ? (closeStock / cogs) * 365 : null;

        var nwcDays = (invDays !== null && arDays !== null && apDays !== null)
            ? invDays + arDays - apDays
            : null;

        // ── Write back ──
        setIfValid('u_cogs',                 cogs);
        setIfValid('u_ebitda',               ebitda);
        setIfValid('u_gross_profit_percent', gpPct);
        setIfValid('u_ebitda_percent',       ebitdaPct);
        setIfValid('u_ar_days',              arDays);
        setIfValid('u_ap_days',              apDays);
        setIfValid('u_inventory_days',       invDays);
        setIfValid('u_net_wcc_days',         nwcDays);

        gs.info('TradeOCR-BR: Complete. EBITDA=' + ebitda + ' EBITDA%=' + ebitdaPct +
                 ' AR Days=' + arDays + ' AP Days=' + apDays + ' Inv Days=' + invDays + ' NWC Days=' + nwcDays);

    } catch (e) {
        gs.error('TradeOCR-BR: Exception — ' + e.message);
    }

})(current, previous);
